INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-27', 'es', 'LAIKA 64 3.6.4: corrección del modo online', 'La partida en línea ya no se queda congelada cuando la conexión directa entre consolas falla en un solo sentido: las consolas vuelven solas a jugar por el servidor y la partida sigue. Todos los jugadores necesitan la misma versión. Actualiza desde LAIKA.'),
 ('2026-11-27', 'en', 'LAIKA 64 3.6.4: online mode fix', 'Online games no longer freeze when the direct connection between consoles fails one way only: the consoles go back to playing through the server by themselves and the game goes on. Every player needs the same version. Update from LAIKA.'),
 ('2026-11-27', 'pt', 'LAIKA 64 3.6.4: correção do modo online', 'A partida online não congela mais quando a conexão direta entre consoles falha em um só sentido: os consoles voltam sozinhos a jogar pelo servidor e a partida continua. Todos os jogadores precisam da mesma versão. Atualize pelo LAIKA.'),
 ('2026-11-27', 'fr', 'LAIKA 64 3.6.4 : correction du mode en ligne', 'La partie en ligne ne se fige plus quand la connexion directe entre consoles échoue dans un seul sens : les consoles repassent seules par le serveur et la partie continue. Tous les joueurs ont besoin de la même version. Mets à jour depuis LAIKA.'),
 ('2026-11-27', 'de', 'LAIKA 64 3.6.4: Korrektur des Online-Modus', 'Online-Spiele frieren nicht mehr ein, wenn die direkte Verbindung zwischen Konsolen nur in eine Richtung ausfällt: Die Konsolen spielen von selbst wieder über den Server weiter. Alle Spieler brauchen dieselbe Version. Aktualisiere in LAIKA.'),
 ('2026-11-27', 'it', 'LAIKA 64 3.6.4: correzione della modalità online', 'La partita online non si blocca più quando la connessione diretta tra console cade in un solo senso: le console tornano da sole a giocare tramite il server e la partita continua. Tutti i giocatori devono avere la stessa versione. Aggiorna da LAIKA.'),
 ('2026-11-27', 'ru', 'LAIKA 64 3.6.4: исправление онлайн-режима', 'Онлайн-игра больше не зависает, когда прямое соединение между консолями пропадает только в одну сторону: консоли сами переходят на игру через сервер, и игра продолжается. Всем игрокам нужна одна версия. Обновитесь в LAIKA.');
